#!/usr/bin/env python3
"""
`todo` -- a small command-line todo list manager.

See SPEC.md for the full specification. State is persisted as a JSON
array of todo-item objects in `./todo.json` (relative to the current
working directory).
"""

import json
import os
import sys

DATA_FILE_NAME = "todo.json"

EXIT_OK = 0
EXIT_DATA_ERROR = 1
EXIT_INVALID_USAGE = 2
EXIT_UNKNOWN_ID = 3


class DataError(Exception):
    """Raised when todo.json exists but is not a valid todo array."""


def _data_file_path():
    return os.path.join(os.getcwd(), DATA_FILE_NAME)


def _validate_items(value):
    """Validate that `value` is a list of well-formed todo-item dicts.

    Raises DataError if not. Returns the list unchanged if valid.
    """
    if not isinstance(value, list):
        raise DataError("todo.json must contain a JSON array")

    for item in value:
        if not isinstance(item, dict):
            raise DataError("todo.json contains an item that is not an object")

        if "id" not in item or "text" not in item or "done" not in item:
            raise DataError("todo.json contains an item missing required fields")

        id_val = item["id"]
        # bool is a subclass of int in Python; explicitly reject it.
        if isinstance(id_val, bool) or not isinstance(id_val, int):
            raise DataError("todo.json contains an item with a non-integer id")

        if not isinstance(item["text"], str):
            raise DataError("todo.json contains an item with a non-string text")

        if not isinstance(item["done"], bool):
            raise DataError("todo.json contains an item with a non-boolean done")

    return value


def load_items():
    """Load todo items from the data file.

    Returns an empty list if the file does not exist. Raises DataError
    if the file exists but is not valid JSON or not a valid todo array.
    """
    path = _data_file_path()
    if not os.path.exists(path):
        return []

    try:
        with open(path, "r", encoding="utf-8") as f:
            raw = f.read()
    except OSError as exc:
        raise DataError(f"could not read {DATA_FILE_NAME}: {exc}")

    try:
        value = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise DataError(f"{DATA_FILE_NAME} is not valid JSON: {exc}")

    return _validate_items(value)


def save_items(items):
    path = _data_file_path()
    with open(path, "w", encoding="utf-8") as f:
        json.dump(items, f, indent=2)
        f.write("\n")


def cmd_add(args):
    if len(args) < 1:
        print("todo add: missing required <text> argument", file=sys.stderr)
        return EXIT_INVALID_USAGE

    text = args[0].strip()
    if not text:
        print("todo add: <text> must not be blank", file=sys.stderr)
        return EXIT_INVALID_USAGE

    try:
        items = load_items()
    except DataError as exc:
        print(f"todo: {exc}", file=sys.stderr)
        return EXIT_DATA_ERROR

    next_id = max((item["id"] for item in items), default=0) + 1
    items.append({"id": next_id, "text": text, "done": False})
    save_items(items)

    print(f"Added todo {next_id}: {text}")
    return EXIT_OK


def cmd_list(args):
    try:
        items = load_items()
    except DataError as exc:
        print(f"todo: {exc}", file=sys.stderr)
        return EXIT_DATA_ERROR

    if not items:
        print("No todos yet.")
        return EXIT_OK

    for item in items:
        marker = "x" if item["done"] else " "
        print(f"[{marker}] {item['id']}. {item['text']}")

    return EXIT_OK


def cmd_done(args):
    if len(args) < 1:
        print("todo done: missing required <id> argument", file=sys.stderr)
        return EXIT_INVALID_USAGE

    try:
        target_id = int(args[0])
    except ValueError:
        print(f"todo done: invalid id {args[0]!r}: must be an integer", file=sys.stderr)
        return EXIT_INVALID_USAGE

    try:
        items = load_items()
    except DataError as exc:
        print(f"todo: {exc}", file=sys.stderr)
        return EXIT_DATA_ERROR

    for item in items:
        if item["id"] == target_id:
            item["done"] = True
            save_items(items)
            print(f"Done: {item['id']}. {item['text']}")
            return EXIT_OK

    print(f"todo done: no todo with id {target_id}", file=sys.stderr)
    return EXIT_UNKNOWN_ID


def main(argv):
    if not argv:
        print("usage: todo <add|list|done> [args]", file=sys.stderr)
        return EXIT_INVALID_USAGE

    command, rest = argv[0], argv[1:]

    if command == "add":
        return cmd_add(rest)
    elif command == "list":
        return cmd_list(rest)
    elif command == "done":
        return cmd_done(rest)
    else:
        print(f"todo: unknown command {command!r}", file=sys.stderr)
        return EXIT_INVALID_USAGE


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

